/**
 * 인라인 SVG 를 만든다. 학습지 HTML 은 외부 요청이 0이어야 하므로 아이콘도 문서에 직접 넣는다.
 * currentColor 를 쓰므로 색은 CSS 가 정한다.
 */
export function icon(name: string, size = 20, extraClass = ''): string {
  const paths = ICON_PATHS[name]
  if (!paths) throw new Error(`등록되지 않은 아이콘: ${name}`)
  return (
    `<svg class="ico${extraClass ? ' ' + extraClass : ''}" width="${size}" height="${size}" ` +
    'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
    paths.map((d) => `<path d="${d}"/>`).join('') +
    '</svg>'
  )
}
